// Generated by tools/build_browser_source_bundle.js.
window.TextAdventureSourceFiles = Object.freeze({"src/bank0.asm":"; Physical bank 0 of the 32K F4 image: splash or immediate boot handoff.\nBANK_ID equ 0\n        include \"data\\splash_config.inc\"\n        if SPLASH_ENABLED = 1\n          include \"splash.asm\"\n        else\n          include \"boot.asm\"\n        endif\n","src/bank1.asm":"; Physical bank 1 of the 32K F4 image: global game logic.\nBANK_ID equ 1\nBANK_ROLE equ 1\n        include \"data\\splash_config.inc\"\n        include \"engine.asm\"\n","src/bank2.asm":"; Physical bank 2 of the 32K F4 image: renderer and story text.\nBANK_ID equ 2\nBANK_ROLE equ 2\n        include \"data\\splash_config.inc\"\n        include \"engine.asm\"\n","src/bank3.asm":"; Physical bank 3 of the 32K F4 image: renderer and story text.\nBANK_ID equ 3\nBANK_ROLE equ 2\n        include \"data\\splash_config.inc\"\n        include \"engine.asm\"\n","src/bank4.asm":"; Physical bank 4 of the 32K F4 image: renderer and story text.\nBANK_ID equ 4\nBANK_ROLE equ 2\n        include \"data\\splash_config.inc\"\n        include \"engine.asm\"\n","src/bank5.asm":"; Physical bank 5 of the 32K F4 image: renderer and story text.\nBANK_ID equ 5\nBANK_ROLE equ 2\n        include \"data\\splash_config.inc\"\n        include \"engine.asm\"\n","src/bank6.asm":"; Physical bank 6 of the 32K F4 image: renderer and story text.\nBANK_ID equ 6\nBANK_ROLE equ 2\n        include \"data\\splash_config.inc\"\n        include \"engine.asm\"\n","src/bank7.asm":"; Physical bank 7 of the 32K F4 image: renderer and story text.\nBANK_ID equ 7\nBANK_ROLE equ 2\n        include \"data\\splash_config.inc\"\n        include \"engine.asm\"\n","src/engine.asm":"; ---------------------------------------------------------------------------\n; Text Adventure 2600 - split logic/renderer for a 32K F4 cartridge\n;\n; Uses the project's native twelve-character string and display method.\n; It does not use the former FOTR room/text engine.\n; Bank 1 owns global game logic. Banks 2-7 clone only the timed renderer and\n; carry seventeen local text scenes each.\n; ---------------------------------------------------------------------------\n\n        processor 6502\n        include \"..\\lib\\vcs.h\"\n        include \"..\\lib\\macro.h\"\n        include \"..\\lib\\xmacro.h\"\n\nLoChar          equ 41\nTHREE_COPIES    equ %011\n\nACTION_LOOK     equ 0\nACTION_NORTH    equ 1\nACTION_EAST     equ 2\nACTION_SOUTH    equ 3\nACTION_WEST     equ 4\nACTION_NEXT     equ 5\nACTION_INVENTORY equ 6\nACTION_COUNT    equ 7\nACTION_CONTEXT equ 7\nACTION_LAST     equ 12            ; six contextual choices per scene\n\nNO_EXIT         equ $FF\nPAGE_MASK       equ $1F\nBANK_MASK       equ $E0\nBANK_0          equ $00\nBANK_1          equ $20\nBANK_2          equ $40\nBANK_3          equ $60\nBANK_4          equ $80\nBANK_5          equ $A0\nBANK_6          equ $C0\nBANK_7          equ $E0\n\n; RAM: only $80-$E1 is used, leaving $E2-$FF for stack headroom.\n        seg.u Variables\n        org $80\n\nTemp            ds 1\nWriteOfs        ds 1\nLoopCount       ds 1\nStrPtr          ds 2\nStrLen          ds 1\nTempSP          ds 1\nPagePtr         ds 2\nCurrentPage     ds 1\nCurrentScene    ds 1            ; global scene index 0-101, used in logic bank\nSelectedAction  ds 1\nInputArmed      ds 1\nCurrentBank     ds 1\nControlMode     ds 1            ; 0=direct movement, 1=LOOK/NEXT selection\nFontBuf         ds 30\nGameFlags       ds 8            ; 64 persistent boolean story flags\nObjectLocations ds 8            ; up to eight portable object locations\nInventoryLineLo ds 11           ; prepared during VBLANK, indexed by row X\nInventoryLineHi ds 11\nActionLineBuffer ds 12          ; context label copied by logic for stable display\nSceneBackgroundColor ds 1       ; effective colour loaded from the current story bank\nSceneActionTextColor ds 1\nSceneActionBackgroundColor ds 1\n\n        seg Code\n        org $F000\n\n        if BANK_ROLE = 1\nStart\n        CLEAN_START\n\n        jsr InitializeGame\n        jmp LogicSelectStoryBank\n\n; The splash has already established a clean TIA state, asserted VBLANK, and\n; started its 30-line overscan timer.  Re-running CLEAN_START here would take\n; roughly 34 scanlines by itself and lengthen the Fire handoff frame.  Clear\n; only the 128 bytes of RIOT RAM, initialize the game inside the still-active\n; splash overscan, and finish that exact timer before starting normal VSYNC.\nStartFromSplash\n        sei\n        cld\n        ldx #$FF\n        txs\n        lda #0\n        ldx #$7F\n.clearRam\n        sta $80,x\n        dex\n        bpl .clearRam\n\n        jsr InitializeGame\n        TIMER_WAIT\n        ; Splash VERTICAL_SYNC has one preliminary alignment WSYNC, whereas\n        ; the game asserts VSYNC immediately. Reproduce that line so this\n        ; transition frame remains 262 scanlines.\n        sta WSYNC\n        jmp LogicSelectStoryBank\n\nInitializeGame subroutine\n        lda #0\n        sta SelectedAction\n        sta ControlMode\n        lda #START_PAGE\n        sta CurrentPage\n        lda #START_SCENE\n        sta CurrentScene\n        lda #START_BANK\n        sta CurrentBank\n        ldx #7\n.initializeFlags\n        lda InitialFlags,x\n        sta GameFlags,x\n        dex\n        bpl .initializeFlags\n        if OBJECT_COUNT > 0\n        ldx #OBJECT_COUNT-1\n.initializeObjects\n        lda InitialObjectLocations,x\n        sta ObjectLocations,x\n        dex\n        bpl .initializeObjects\n        endif\n        jsr ResolvePageVariant\n        ; A released controller is required before the first game input. This\n        ; also consumes the Fire press used to leave an optional splash.\n        lda #0\n        sta InputArmed\n        rts\n        endif\n\n        if BANK_ROLE = 2\nNextFrame\n        lda #2\n        sta VBLANK\n        sta VSYNC\n        TIMER_SETUP 3\n\n        jsr SetupBackground\n        TIMER_WAIT\n\n        lda #0\n        sta VSYNC\n        ; Match the established Text Adventure 2600 NTSC frame: 37 lines of vertical\n        ; blank after the three-line VSYNC interval.\n        TIMER_SETUP 37\n\n        jsr PrepareText\n        jsr LoadPagePointer\n\n        ; The first line is built during vertical blank. Remaining lines are\n        ; built between DrawText calls using the stable display sequence.\n        ldx #10\n        lda ControlMode\n        cmp #2\n        beq .prepareInventory\n        ; Resolve the variable action-label pointer outside the visible kernel.\n        ; InventoryLine[0] is free in story/action mode and provides a two-byte\n        ; cache without consuming additional console RAM.\n        jsr PrepareActionPointer\n        ldx #10                    ; ending lookup uses X; restore the top row\n        jsr SelectLinePointer\n        jmp .buildFirstLine\n.prepareInventory\n        jsr PrepareInventoryPointers\n        ldx #10                    ; cache preparation uses X; restore top row\n        jsr SelectInventoryLinePointer\n.buildFirstLine\n        jsr BuildText\n\n        TIMER_WAIT\n        lda #0\n        sta VBLANK\n        ; The Text Adventure 2600 kernel uses a 192-line visible interval.\n        ; Together with 3 VSYNC, 37 VBLANK and 30 overscan lines this keeps the\n        ; frame at exactly 262 lines and restores blank space above and below.\n        TIMER_SETUP 192\n\n        ldx #0\n.topSpace\n        sta WSYNC\n        inx\n        cpx #10\n        bne .topSpace\n\n        lda ControlMode\n        cmp #2\n        beq .showInventory\n        jsr ShowText\n        jmp .visibleDone\n.showInventory\n        jsr ShowInventory\n.visibleDone\n        TIMER_WAIT\n\n        lda #2\n        sta VBLANK\n        TIMER_SETUP 30\n        jmp StorySelectLogicBank\n\n; ---------------------------------------------------------------------------\n; Display setup and kernel. These routines retain the timing and RAM bitmap\n; construction of the stable Text Adventure 2600 renderer.\n; ---------------------------------------------------------------------------\n\nSetupBackground subroutine\n        ldx CurrentPage\n        lda SceneBackgroundColors,x\n        sta SceneBackgroundColor\n        sta COLUBK\n        lda SceneBorderColors,x\n        sta COLUPF\n        lda SceneTextColors,x\n        sta COLUP0\n        sta COLUP1\n        lda SceneActionTextColors,x\n        sta SceneActionTextColor\n        lda SceneActionBackgroundColors,x\n        sta SceneActionBackgroundColor\n        lda SceneBorderStyles,x\n        and #1                    ; bit 7 marks an ending scene\n        bne .solidBorder\n        ; Ten outer playfield columns form striped side panels. The inner ten\n        ; columns stay clear so COLUBK remains the text-area colour.\n        lda #%10100000\n        sta PF0\n        lda #%01010100\n        sta PF1\n        lda #0\n        sta PF2\n        jmp .borderReady\n.solidBorder\n        ; Fill the same ten outer columns for solid side panels.\n        lda #%11110000\n        sta PF0\n        lda #%11111100\n        sta PF1\n        lda #0\n        sta PF2\n.borderReady\n        lda #%00000001\n        sta CTRLPF\n        rts\n\nPrepareText subroutine\n        lda #THREE_COPIES\n        sta NUSIZ0\n        sta NUSIZ1\n        sta WSYNC\n        SLEEP 36\n        sta RESP0\n        sta RESP1\n        lda #$10\n        sta HMP1\n        sta WSYNC\n        sta HMOVE\n        lda #1\n        sta VDELP0\n        sta VDELP1\n        rts\n\n; The action row is still drawn by the unchanged five-scanline text kernel.\n; Its colours change at the row boundary, outside DrawText, so none of the\n; cycle-sensitive character writes are disturbed. The playfield is untouched:\n; the configured side panels remain visible beside the centre action area.\nPrepareActionRowStyle subroutine\n        lda SceneActionTextColor\n        sta COLUP0\n        sta COLUP1\n        lda SceneActionBackgroundColor\n        sta COLUBK\n        rts\n\nFinishActionRowStyle subroutine\n        lda SceneBackgroundColor\n        sta COLUBK\n        rts\n\n; Build the 48x5 bitmap for the twelve native character bytes at StrPtr.\nBuildText subroutine\n        tsx\n        stx TempSP\n        lda #FontBuf+4\n        sta WriteOfs\n        ldy #0\n        sty StrLen\n.charLoop\n        lda (StrPtr),y\n        sec\n        sbc #LoChar\n        sta Temp\n        asl\n        asl\n        adc Temp\n        tax\n\n        iny\n        lda (StrPtr),y\n        sec\n        sbc #LoChar\n        sta Temp\n        asl\n        asl\n        adc Temp\n        iny\n        sty StrLen\n        tay\n\n        txa\n        ldx WriteOfs\n        txs\n        tax\n\n        lda FontTableLo+4,y\n        ora FontTableHi+4,x\n        pha\n        lda FontTableLo+3,y\n        ora FontTableHi+3,x\n        pha\n        lda FontTableLo+2,y\n        ora FontTableHi+2,x\n        pha\n        lda FontTableLo+1,y\n        ora FontTableHi+1,x\n        pha\n        lda FontTableLo,y\n        ora FontTableHi,x\n        pha\n\n        lda WriteOfs\n        clc\n        adc #5\n        sta WriteOfs\n        ldy StrLen\n        cpy #12\n        bne .charLoop\n\n        ldx TempSP\n        txs\n        rts\n\nDrawText subroutine\n        lda #4\n        sta LoopCount\n.scanline\n        sta WSYNC\n        ldy LoopCount\n        lda FontBuf+0,y\n        sta GRP0\n        lda FontBuf+5,y\n        sta GRP1\n        lda FontBuf+10,y\n        sta GRP0\n        lda FontBuf+25,y\n        sta Temp\n        ldx FontBuf+20,y\n        lda FontBuf+15,y\n        ldy Temp\n        sta GRP1\n        stx GRP0\n        sty GRP1\n        sta GRP0\n        dec LoopCount\n        lda LoopCount\n        cmp #$FF\n        bne .scanline\n\n        lda #0\n        sta GRP0\n        sta GRP1\n        sta GRP0\n        sta GRP1\n        rts\n\n; X=10 is the top story row. X=1 is the tenth story row. X=0 is\n; deliberately and permanently the action-selection row.\nShowText subroutine\n        ldx #10\n.lineLoop\n        txa\n        pha\n        jsr DrawText\n        pla\n        tax\n        dex\n        bmi .done\n\n        txa\n        pha\n        jsr SelectLinePointer\n        jsr BuildText\n        pla\n        tax\n        cpx #0\n        bne .nextLine\n        jsr PrepareActionRowStyle\n.nextLine\n        jmp .lineLoop\n.done\n        jsr FinishActionRowStyle\n        rts\n\nShowInventory subroutine\n        ldx #10\n.lineLoop\n        txa\n        pha\n        jsr DrawText\n        pla\n        tax\n        dex\n        bmi .done\n\n        txa\n        pha\n        jsr SelectInventoryLinePointer\n        jsr BuildText\n        pla\n        tax\n        cpx #0\n        bne .nextLine\n        jsr PrepareActionRowStyle\n.nextLine\n        jmp .lineLoop\n.done\n        jsr FinishActionRowStyle\n        rts\n\nLoadPagePointer subroutine\n        ldx CurrentPage\n        lda PageTextLo,x\n        sta PagePtr\n        lda PageTextHi,x\n        sta PagePtr+1\n        rts\n\n; Cache the final row's source pointer during VBLANK. Selecting a built-in or\n; contextual action takes more cycles than selecting MOVE; doing that work\n; here keeps the visible action row on exactly the same scanline in every mode.\nPrepareActionPointer subroutine\n        ldx CurrentPage\n        lda SceneBorderStyles,x\n        bmi .restart\n        lda ControlMode\n        bne .selectedAction\n        lda #<MovePrompt\n        sta InventoryLineLo\n        lda #>MovePrompt\n        sta InventoryLineHi\n        rts\n\n.selectedAction\n        ldy SelectedAction\n        cpy #ACTION_CONTEXT\n        bcs .contextAction\n        lda ActionTextLo,y\n        sta InventoryLineLo\n        lda ActionTextHi,y\n        sta InventoryLineHi\n        rts\n.contextAction\n        lda #<ActionLineBuffer\n        sta InventoryLineLo\n        lda #>ActionLineBuffer\n        sta InventoryLineHi\n        rts\n.restart\n        lda #<ActionRestart\n        sta InventoryLineLo\n        lda #>ActionRestart\n        sta InventoryLineHi\n        rts\n\n; Select a story row or, for X=0, the independent action row.\nSelectLinePointer subroutine\n        cpx #0\n        beq .action\n\n        lda PagePtr\n        clc\n        adc LineOffsets,x\n        sta StrPtr\n        lda PagePtr+1\n        adc #0\n        sta StrPtr+1\n        rts\n\n.action\n        ; Match the former MOVE path's 26-cycle timing for every label.\n        SLEEP 3\n        lda InventoryLineLo\n        sta StrPtr\n        lda InventoryLineHi\n        sta StrPtr+1\n        rts\n\nSelectInventoryLinePointer subroutine\n        ; Match the ordinary story-pointer path so inventory rows retain the\n        ; same vertical cadence while still avoiding a variable object scan.\n        SLEEP 7\n        lda InventoryLineLo,x\n        sta StrPtr\n        lda InventoryLineHi,x\n        sta StrPtr+1\n        rts\n\n; Build the inventory's complete row-pointer table outside the drawable area.\n; The visible kernel then performs no object scan and cannot overrun its timer.\nPrepareInventoryPointers subroutine\n        ldx #10\n.blankRows\n        lda #<BlankLine\n        sta InventoryLineLo,x\n        lda #>BlankLine\n        sta InventoryLineHi,x\n        dex\n        bpl .blankRows\n\n        lda #<InventoryTitle\n        sta InventoryLineLo+10\n        lda #>InventoryTitle\n        sta InventoryLineHi+10\n        lda #<InventoryReturn\n        sta InventoryLineLo\n        lda #>InventoryReturn\n        sta InventoryLineHi\n\n        if OBJECT_COUNT > 0\n        lda #9\n        sta Temp\n        ldy #0\n.object\n        lda ObjectLocations,y\n        cmp #$FE\n        bne .nextObject\n        ldx Temp\n        lda ObjectNameLo,y\n        sta InventoryLineLo,x\n        lda ObjectNameHi,y\n        sta InventoryLineHi,x\n        dec Temp\n.nextObject\n        iny\n        cpy #OBJECT_COUNT\n        bne .object\n        endif\n        rts\n\n; Display indexes 10..1 correspond to byte offsets 0,12..108.\nLineOffsets\n        dc.b 0,108,96,84,72,60,48,36,24,12,0\n\nActionTextLo\n        dc.b <ActionLook,<ActionNorth,<ActionEast\n        dc.b <ActionSouth,<ActionWest,<ActionNext,<ActionInventory\nActionTextHi\n        dc.b >ActionLook,>ActionNorth,>ActionEast\n        dc.b >ActionSouth,>ActionWest,>ActionNext,>ActionInventory\n\n; Keep all fixed 12-byte strings within one 256-byte ROM page. BuildText uses\n; (StrPtr),Y; crossing a page adds a cycle and can move this bottom row by a\n; scanline when the selected action changes.\n        align $100\nMovePrompt      dc.b \"MOVE:[NSEW[[\"\nActionLook      dc.b \"ACT:[LOOK[[[\"\nActionNorth     dc.b \"ACT:[NORTH[[\"\nActionEast      dc.b \"ACT:[EAST[[[\"\nActionSouth     dc.b \"ACT:[SOUTH[[\"\nActionWest      dc.b \"ACT:[WEST[[[\"\nActionNext      dc.b \"ACT:[NEXT[[[\"\nActionInventory dc.b \"INVENTORY[[[\"\nActionRestart   dc.b \"FIRE:RESTART\"\nInventoryTitle  dc.b \"[INVENTORY[[\"\nInventoryReturn dc.b \"FIRE:[RETURN\"\nBlankLine       dc.b \"[[[[[[[[[[[[\"\n        endif\n\n; ---------------------------------------------------------------------------\n; Controller and minimal page engine.\n; In movement mode the four joystick directions directly follow the matching\n; PageActions destination. Fire enters action mode without executing anything.\n; In action mode any direction cycles valid LOOK/NEXT/contextual choices and\n; Fire confirms the displayed choice.\n; Each page has six destination bytes in LOOK,NORTH,EAST,SOUTH,WEST,NEXT order.\n; Destinations pack the F4 bank into bits 7..5 and page index into bits 4..0.\n; $FF means unavailable; story page indexes are 0..16.\n; ---------------------------------------------------------------------------\n\n        if BANK_ROLE = 1\nLogicOverscan\n        jsr ReadControls\n        jsr PrepareContextActionLine\n        TIMER_WAIT\n        jmp LogicSelectStoryBank\n\nReadControls subroutine\n        ; Rearm only after every direction and fire have all been released.\n        lda SWCHA\n        and #%11110000\n        cmp #%11110000\n        bne .pressed\n        lda INPT4\n        bpl .pressed\n        lda #1\n        sta InputArmed\n        rts\n\n.pressed\n        lda InputArmed\n        bne .inputArmed\n        jmp .done\n.inputArmed\n\n        ; Ending scenes deliberately suppress movement, inventory, NEXT and\n        ; contextual actions. Fire restores the complete initial game state.\n        ldx CurrentScene\n        lda PageEndings,x\n        beq .normalControls\n        lda INPT4\n        bpl .restartGame\n        jmp .done\n.restartGame\n        jsr InitializeGame\n        jmp .consume\n\n.normalControls\n\n        lda ControlMode\n        cmp #2\n        beq .inventoryMode\n        lda ControlMode\n        bne .actionMode\n\n        ; Movement has priority if fire and a direction are pressed together.\n        lda SWCHA\n        and #%00010000\n        beq .north\n        lda SWCHA\n        and #%10000000\n        beq .east\n        lda SWCHA\n        and #%00100000\n        beq .south\n        lda SWCHA\n        and #%01000000\n        beq .west\n        lda INPT4\n        bmi .done\n        lda #1\n        sta ControlMode\n        lda #ACTION_LOOK\n        sta SelectedAction\n        jmp .consume\n\n.north\n        lda #ACTION_NORTH\n        bne .move\n.east\n        lda #ACTION_EAST\n        bne .move\n.south\n        lda #ACTION_SOUTH\n        bne .move\n.west\n        lda #ACTION_WEST\n.move\n        sta SelectedAction\n        jsr PerformAction\n        jmp .consume\n\n.actionMode\n        ; A direction cycles valid LOOK/NEXT/contextual choices. It never\n        ; executes one, so an imprecise fire/direction chord remains harmless.\n        lda SWCHA\n        and #%11110000\n        cmp #%11110000\n        bne .toggleAction\n        lda INPT4\n        bmi .done\n        jsr PerformAction\n        lda ControlMode\n        cmp #2\n        beq .consume\n        lda #0\n        sta ControlMode\n        jmp .consume\n\n.inventoryMode\n        lda INPT4\n        bmi .done\n        lda #0\n        sta ControlMode\n        jmp .consume\n\n.toggleAction\n        jsr SelectNextAction\n\n.consume\n        lda #0\n        sta InputArmed\n.done\n        rts\n\nPerformAction subroutine\n        lda SelectedAction\n        cmp #ACTION_INVENTORY\n        beq .inventory\n        cmp #ACTION_CONTEXT\n        bcc .standard\n        jsr ApplyContextAction\n        jsr ResolvePageVariant\n        rts\n.inventory\n        lda #2\n        sta ControlMode\n        rts\n.standard\n        ; Effects are read from the source bank before a destination can switch\n        ; the cartridge to another physical bank.\n        jsr ApplyFlagEffects\n\n        jsr LoadSelectedDestination\n        cmp #NO_EXIT\n        beq .resolve\n        jsr ApplyDestination\n.resolve\n        lda SelectedAction\n        cmp #ACTION_NEXT\n        beq .done\n        jsr ResolvePageVariant\n.done\n        rts\n\n; Cycle LOOK, NEXT (when linked), and up to six flag-qualified scene actions.\nSelectNextAction subroutine\n.try\n        lda SelectedAction\n        cmp #ACTION_LOOK\n        beq .selectNext\n        cmp #ACTION_LAST\n        bcs .selectLook\n        clc\n        adc #1\n        bne .test\n.selectNext\n        lda #ACTION_NEXT\n        bne .test\n.selectLook\n        lda #ACTION_LOOK\n.test\n        sta SelectedAction\n        jsr SelectedActionAvailable\n        bcc .try\n        rts\n\nSelectedActionAvailable subroutine\n        lda SelectedAction\n        beq .yes\n        cmp #ACTION_INVENTORY\n        beq .yes\n        cmp #ACTION_NEXT\n        bne ContextActionAvailable\n        lda #ACTION_NEXT\n        jsr LoadActionDestination\n        cmp #NO_EXIT\n        beq .no\n.yes\n        sec\n        rts\n.no\n        clc\n        rts\n\n; Locate SelectedAction's variable-length record. Returns C=1 and Y at its\n; two-byte label pointer, or C=0 if the scene does not define that ordinal.\nFindContextAction subroutine\n        ldx CurrentScene\n        lda PageContextLo,x\n        sta StrPtr\n        lda PageContextHi,x\n        sta StrPtr+1\n        ldy #0\n        lda SelectedAction\n        sec\n        sbc #ACTION_CONTEXT\n        sta LoopCount\n        cmp (StrPtr),y\n        bcs .missing\n        iny\n.record\n        lda LoopCount\n        beq .found\n        iny\n        iny\n.skipRequirements\n        lda (StrPtr),y\n        iny\n        cmp #$FF\n        bne .skipRequirements\n.skipObjectRequirements\n        lda (StrPtr),y\n        iny\n        cmp #$FF\n        bne .skipObjectRequirements\n.skipEffects\n        lda (StrPtr),y\n        iny\n        cmp #$FF\n        bne .skipEffects\n.skipObjectEffects\n        lda (StrPtr),y\n        iny\n        cmp #$FF\n        bne .skipObjectEffects\n        dec LoopCount\n        jmp .record\n.found\n        sec\n        rts\n.missing\n        clc\n        rts\n\nContextActionAvailable subroutine\n        jsr FindContextAction\n        bcc .failed\n        iny\n        iny\n.condition\n        lda (StrPtr),y\n        cmp #$FF\n        beq .objectConditions\n        sta WriteOfs\n        iny\n        jsr TestFlagCondition\n        bcs .condition\n.failed\n        clc\n        rts\n.objectConditions\n        iny\n.objectCondition\n        lda (StrPtr),y\n        cmp #$FF\n        beq .passed\n        sta WriteOfs\n        iny\n        and #$3F\n        tax\n        lda ObjectLocations,x\n        sta Temp\n        lda WriteOfs\n        and #$C0\n        cmp #$40\n        beq .requireHere\n        lda Temp\n        cmp #$FE\n        beq .objectCondition\n        bne .failed\n.requireHere\n        lda Temp\n        ldx CurrentScene\n        cmp PageRoomLocations,x\n        beq .objectCondition\n        bne .failed\n.passed\n        sec\n        rts\n\nApplyContextAction subroutine\n        jsr FindContextAction\n        bcc .done\n        iny\n        iny\n.skipRequirements\n        lda (StrPtr),y\n        iny\n        cmp #$FF\n        bne .skipRequirements\n.skipObjectRequirements\n        lda (StrPtr),y\n        iny\n        cmp #$FF\n        bne .skipObjectRequirements\n.effect\n        lda (StrPtr),y\n        cmp #$FF\n        beq .objectEffects\n        iny\n        jsr ApplyFlagOperation\n        jmp .effect\n.objectEffects\n        iny\n.objectEffect\n        lda (StrPtr),y\n        cmp #$FF\n        beq .done\n        sta WriteOfs\n        iny\n        and #$3F\n        tax\n        lda WriteOfs\n        and #$C0\n        beq .takeObject\n        lda #$FF\n        bne .storeObject\n.takeObject\n        lda #$FE\n.storeObject\n        sta ObjectLocations,x\n        jmp .objectEffect\n.done\n        rts\n\nApplyDestination subroutine\n        sta Temp\n        and #PAGE_MASK\n        sta CurrentPage\n        lda Temp\n        and #BANK_MASK\n        lsr\n        lsr\n        lsr\n        lsr\n        lsr\n        sta CurrentBank\nUpdateCurrentScene subroutine\n        ldx CurrentBank\n        lda StoryBankOffsets,x\n        clc\n        adc CurrentPage\n        sta CurrentScene\n        rts\n\nLoadSelectedDestination subroutine\n        lda SelectedAction\nLoadActionDestination subroutine\n        tay\n        lda ActionTableLo,y\n        sta StrPtr\n        lda ActionTableHi,y\n        sta StrPtr+1\n        ldy CurrentScene\n        lda (StrPtr),y\n        rts\n\n; PageEffects is a compact bank-local list. Records contain source page,\n; action, encoded operations, then $FF; $FE terminates the complete table.\nApplyFlagEffects subroutine\n        lda #<PageEffects\n        sta StrPtr\n        lda #>PageEffects\n        sta StrPtr+1\n        ldy #0\n.record\n        lda (StrPtr),y\n        cmp #$FE\n        beq .done\n        sta Temp\n        iny\n        lda (StrPtr),y\n        sta LoopCount\n        iny\n        lda Temp\n        cmp CurrentScene\n        bne .skip\n        lda LoopCount\n        cmp SelectedAction\n        bne .skip\n.apply\n        lda (StrPtr),y\n        cmp #$FF\n        beq .done\n        iny\n        jsr ApplyFlagOperation\n        jmp .apply\n.skip\n        lda (StrPtr),y\n        iny\n        cmp #$FF\n        bne .skip\n        jmp .record\n.done\n        rts\n\n; A encodes SET=$00, CLEAR=$40, TOGGLE=$80 plus a six-bit flag index.\nApplyFlagOperation subroutine\n        sta WriteOfs\n        and #$3F\n        sta LoopCount\n        and #7\n        tax\n        lda FlagMasks,x\n        sta StrLen\n        lda LoopCount\n        lsr\n        lsr\n        lsr\n        tax\n        lda WriteOfs\n        and #$C0\n        beq .set\n        cmp #$40\n        beq .clear\n        lda GameFlags,x\n        eor StrLen\n        sta GameFlags,x\n        rts\n.set\n        lda GameFlags,x\n        ora StrLen\n        sta GameFlags,x\n        rts\n.clear\n        lda StrLen\n        eor #$FF\n        and GameFlags,x\n        sta GameFlags,x\n        rts\n\n; The first ordered rule whose conditions pass replaces the current scene. A rule\n; stores SET requirements as $00-$3F and CLEAR requirements as $80-$BF.\nResolvePageVariant subroutine\n        ldx CurrentScene\n        lda PageVariantLo,x\n        sta StrPtr\n        lda PageVariantHi,x\n        sta StrPtr+1\n        ldy #0\n.rule\n        lda (StrPtr),y\n        cmp #$FE\n        beq .done\n        lda #1\n        sta PagePtr\n.condition\n        lda (StrPtr),y\n        cmp #$FF\n        beq .destination\n        sta WriteOfs\n        iny\n        jsr TestFlagCondition\n        bcs .condition\n        lda #0\n        sta PagePtr\n        jmp .condition\n.destination\n        iny\n        lda (StrPtr),y\n        iny\n        ldx PagePtr\n        beq .rule\n        jsr ApplyDestination\n.done\n        rts\n\nTestFlagCondition subroutine\n        lda WriteOfs\n        and #$3F\n        sta LoopCount\n        and #7\n        tax\n        lda FlagMasks,x\n        sta StrLen\n        lda LoopCount\n        lsr\n        lsr\n        lsr\n        tax\n        lda GameFlags,x\n        and StrLen\n        sta LoopCount\n        lda WriteOfs\n        bmi .requireClear\n        lda LoopCount\n        beq .failed\n        sec\n        rts\n.requireClear\n        lda LoopCount\n        bne .failed\n        sec\n        rts\n.failed\n        clc\n        rts\n\nFlagMasks\n        dc.b $01,$02,$04,$08,$10,$20,$40,$80\n\nPrepareContextActionLine subroutine\n        lda ControlMode\n        cmp #1\n        bne .done\n        lda SelectedAction\n        cmp #ACTION_CONTEXT\n        bcc .done\n        jsr FindContextAction\n        bcc .done\n        lda (StrPtr),y\n        sta Temp\n        iny\n        lda (StrPtr),y\n        sta StrPtr+1\n        lda Temp\n        sta StrPtr\n        ldy #0\n.copy\n        lda (StrPtr),y\n        sta ActionLineBuffer,y\n        iny\n        cpy #12\n        bne .copy\n.done\n        rts\n        endif\n\n; Renderer-local strings, object-name pointers and text pointers fit below the\n; cross-bank landing slots. The timed font occupies $F500-$F6FF.\n        if BANK_ROLE = 2\n        org $F400\n          if BANK_ID = 2\n            include \"data\\bank2_context_labels.inc\"\n            include \"data\\bank2_story.inc\"\n          endif\n          if BANK_ID = 3\n            include \"data\\bank3_context_labels.inc\"\n            include \"data\\bank3_story.inc\"\n          endif\n          if BANK_ID = 4\n            include \"data\\bank4_context_labels.inc\"\n            include \"data\\bank4_story.inc\"\n          endif\n          if BANK_ID = 5\n            include \"data\\bank5_context_labels.inc\"\n            include \"data\\bank5_story.inc\"\n          endif\n          if BANK_ID = 6\n            include \"data\\bank6_context_labels.inc\"\n            include \"data\\bank6_story.inc\"\n          endif\n          if BANK_ID = 7\n            include \"data\\bank7_context_labels.inc\"\n            include \"data\\bank7_story.inc\"\n          endif\n        endif\n\n; Story renderer -> logic bank. The LDA changes banks; bank 1 continues at\n; $F4C3 and jumps into its overscan handler.\n        org $F4C0\n        if BANK_ROLE = 2\nStorySelectLogicBank\n        lda $1FF5\n        else\n        dc.b 0,0,0\nLogicOverscanLanding\n        jmp LogicOverscan\n        endif\n\n; Logic bank -> selected story bank. The target renderer continues at $F4D5.\n        org $F4D0\n        if BANK_ROLE = 1\nLogicSelectStoryBank\n        ldx CurrentBank\n        lda $1FF4,x\n        else\n        dc.b 0,0,0,0,0\nStoryFrameLanding\n        jmp NextFrame\n        endif\n\n; Cold-boot and splash handoff landings from bank 0.\n        org $F4E0\n        if BANK_ROLE = 1\n        dc.b 0,0,0\nColdBootLanding\n        jmp Start\n        endif\n        org $F4F0\n        if BANK_ROLE = 1\n        dc.b 0,0,0\nSplashGameLanding\n        jmp StartFromSplash\n        endif\n\n        if BANK_ROLE = 2\n        org $F500\n        include \"text_adventure_font.inc\"\n          if BANK_ID = 2\n            include \"data\\bank2_text.inc\"\n          endif\n          if BANK_ID = 3\n            include \"data\\bank3_text.inc\"\n          endif\n          if BANK_ID = 4\n            include \"data\\bank4_text.inc\"\n          endif\n          if BANK_ID = 5\n            include \"data\\bank5_text.inc\"\n          endif\n          if BANK_ID = 6\n            include \"data\\bank6_text.inc\"\n          endif\n          if BANK_ID = 7\n            include \"data\\bank7_text.inc\"\n          endif\n        else\n        include \"data\\logic_story.inc\"\n        endif\n\n; Every bank routes reset through bank 0. Bank 0 carries the same landing JMP.\n        org $FFE0\nResetEntry\n        bit $1FF4\n        jmp $F000\n\n        org $FFFC\n        dc.w ResetEntry\n        dc.w ResetEntry\n","src/boot.asm":"; Bank-0 boot path used when no splash artwork is enabled.\n        processor 6502\n        include \"..\\lib\\vcs.h\"\n        include \"..\\lib\\macro.h\"\n\n        seg BootCode\n        org $F000\nBootStart\n        CLEAN_START\n        jmp BootSelectLogicBank\n\n; Select F4 bank 1. Instruction fetching resumes in logic bank 1 at $F4E3.\n        org $F4E0\nBootSelectLogicBank\n        lda $1FF5\n        jmp BootStart\n\n; Reset from any bank first selects bank 0 and then executes the shared JMP.\n        org $FFE0\nBootResetEntry\n        bit $1FF4\n        jmp $F000\n\n        org $FFFC\n        dc.w BootResetEntry\n        dc.w BootResetEntry\n","src/splash.asm":"; ---------------------------------------------------------------------------\n; Optional colour splash bank.\n; Artwork is extracted from the editor upload; uploaded code is never run.\n; The frame layout and delayed, release-gated Fire handoff follow the proven\n; Kosho splash approach so the transition cannot shorten or lengthen a frame.\n; ---------------------------------------------------------------------------\n\n        processor 6502\n        include \"..\\lib\\vcs.h\"\n        include \"..\\lib\\macro.h\"\n        include \"..\\lib\\xmacro.h\"\n\n        seg.u SplashVariables\n        org $80\nSplashTemp              ds 1\nSplashHeightCounter     ds 1\nSplashDelayCounter      ds 1\nSplashFireArmed         ds 1\n\n        seg SplashCode\n        org $F000\n\nSplashStart\n        CLEAN_START\n        lda #1\n        sta CTRLPF\n        lda #SPLASH_BACKGROUND_COLOR\n        sta COLUBK\n        lda #SPLASH_DELAY_FRAMES\n        sta SplashDelayCounter\n        lda #0\n        sta SplashFireArmed\n\nSplashNextFrame\n        VERTICAL_SYNC\n        lda #44\n        sta TIM64T\n\nSplashWaitVBlank\n        lda INTIM\n        bne SplashWaitVBlank\n        sta WSYNC\n        sta VBLANK\n\n        ldx #SPLASH_PADDING_LINES\nSplashPaddingLoop\n        sta WSYNC\n        dex\n        bne SplashPaddingLoop\n\n        ldx #SPLASH_PLAYFIELD_LINES-1\n        lda #SPLASH_LINE_HEIGHT\n        sta SplashHeightCounter\n\nSplashPlayfieldLoop\n        sta WSYNC\n        lda SplashPFColors,x\n        sta COLUPF\n        lda SplashPF0DataA,x\n        sta PF0\n        lda SplashPF1DataA,x\n        sta PF1\n        lda SplashPF2DataA,x\n        sta PF2\n        lda SplashPF2DataB,x\n        tay\n        lda SplashPF1DataB,x\n        sta PF1\n        lda SplashPF0DataB,x\n        sty PF2\n        sta PF0\n        dec SplashHeightCounter\n        bne SplashSameRow\n        lda #SPLASH_LINE_HEIGHT\n        sta SplashHeightCounter\n        dex\n        cpx #$FF\n        beq SplashDoneRows\nSplashSameRow\n        jmp SplashPlayfieldLoop\n\nSplashDoneRows\n        lda #0\n        sta PF0\n        sta PF1\n        sta PF2\n        ldx #SPLASH_REMAINING_LINES\nSplashVisibleRemainder\n        sta WSYNC\n        dex\n        bne SplashVisibleRemainder\n\n        lda #36\n        sta TIM64T\n        lda #2\n        sta WSYNC\n        sta VBLANK\n\n        lda SplashDelayCounter\n        beq SplashCheckFire\n        dec SplashDelayCounter\n        jmp SplashWaitOverscan\n\nSplashCheckFire\n        lda SplashFireArmed\n        bne SplashFireReady\n        bit INPT4\n        bpl SplashWaitOverscan\n        lda #1\n        sta SplashFireArmed\n        bne SplashWaitOverscan\nSplashFireReady\n        bit INPT4\n        bpl SplashStartGame\n\nSplashWaitOverscan\n        lda INTIM\n        bne SplashWaitOverscan\n        sta WSYNC\n        jmp SplashNextFrame\n\nSplashStartGame\n        lda #0\n        sta AUDV0\n        sta AUDV1\n        jmp SplashSelectLogicBank\n\n; Select F4 bank 1. Logic execution continues at $F4F3.\n        org $F4F0\nSplashSelectLogicBank\n        lda $1FF5\n        jmp SplashStart              ; only used if an invalid bank was chosen\n\n        include \"data\\splash_art.inc\"\n\n; Reset from every physical bank selects bank 0 before entering the splash.\n        org $FFE0\nSplashResetEntry\n        bit $1FF4\n        jmp $F000\n\n        org $FFFC\n        dc.w SplashResetEntry\n        dc.w SplashResetEntry\n","src/text_adventure_font.inc":"; Unpacked 4x5 font tables used by Text Adventure 2600.\n; Characters are ordinary byte values from ASCII 41 through 91. The sample\n; text uses '[' (91) as a blank, just like the reference program.\n\n        align $100\nFontTableLo\n        hex 0402020204050205000002070200000402000000070000000004000000000404\n        hex 0201010605050503020202060207040201060601020106010107050506010604\n        hex 0707050704030404020107070507050706010705070400040000040200020001\n        hex 0204020107000700000402010204020002010703040705020505070502060506\n        hex 0506030404040306050505060704070407040407040703050704030505070505\n        hex 0702020207020501010105050605050704040404050507070505070707050205\n        hex 0505020404060506030705050205060705060601020403020202020703050505\n        hex 0502020505050507070505050502050502020205050704020107000000000000\n\n        align $100\nFontTableHi\n        hex 4020202040502050000020702000004020000000700000000040000000004040\n        hex 2010106050505030202020602070402010606010201060101070505060106040\n        hex 7070507040304040201070705070507060107050704000400000402000200010\n        hex 2040201070007000004020102040200020107030407050205050705020605060\n        hex 5060304040403060505050607040704070404070407030507040305050705050\n        hex 7020202070205010101050506050507040404040505070705050707070502050\n        hex 5050204040605060307050502050607050606010204030202020207030505050\n        hex 5020205050505070705050505020505020202050507040201070000000000000\n","lib/vcs.h":"; Text Adventure 2600 hardware-register definitions.\n; This deliberately small include contains only the TIA and RIOT registers used\n; by this project. The addresses come from the public Atari 2600 hardware map.\n\n; TIA write registers\nVSYNC   = $00\nVBLANK  = $01\nWSYNC   = $02\nNUSIZ0  = $04\nNUSIZ1  = $05\nCOLUP0  = $06\nCOLUP1  = $07\nCOLUPF  = $08\nCOLUBK  = $09\nCTRLPF  = $0A\nPF0     = $0D\nPF1     = $0E\nPF2     = $0F\nRESP0   = $10\nRESP1   = $11\nAUDV0   = $19\nAUDV1   = $1A\nGRP0    = $1B\nGRP1    = $1C\nHMP1    = $21\nVDELP0  = $25\nVDELP1  = $26\nHMOVE   = $2A\n\n; TIA read registers\nINPT4   = $0C\n\n; RIOT I/O and timer registers\nSWCHA   = $0280\nINTIM   = $0284\nTIM64T  = $0296\n","lib/macro.h":"; Text Adventure 2600 startup and display-timing macros.\n\n; Insert an exact delay of two or more processor cycles. Odd delays use the\n; legal three-cycle BIT instruction; the remaining delay is filled with NOPs.\n    MAC SLEEP\n.cycles SET {1}\n        IF .cycles < 2\n            ECHO \"MACRO ERROR: SLEEP duration must be at least 2 cycles\"\n            ERR\n        ENDIF\n        IF .cycles & 1\n            bit VSYNC\n.cycles SET .cycles - 3\n        ENDIF\n        REPEAT .cycles / 2\n            nop\n        REPEND\n    ENDM\n\n; Clear TIA and zero-page RAM and leave A, X, Y and the stack in a known state.\n    MAC CLEAN_START\n        sei\n        cld\n        ldx #$FF\n        txs\n        inx\n        txa\n        tay\n.clear\n        sta $00,x\n        inx\n        bne .clear\n    ENDM\n\n; Align to a scanline, assert VSYNC for three complete scanlines, then clear it.\n; A is zero on return.\n    MAC VERTICAL_SYNC\n        lda #2\n        sta WSYNC\n        sta VSYNC\n        sta WSYNC\n        sta WSYNC\n        sta WSYNC\n        lda #0\n        sta VSYNC\n    ENDM\n","lib/xmacro.h":"; Text Adventure 2600 scanline timer helpers.\n\n; Start a 64-clock RIOT timer for the requested number of scanlines. The first\n; WSYNC aligns the calculation to a complete scanline.\n    MAC TIMER_SETUP\n.lines  SET {1}\n.cycles SET ((.lines * 76) - 13)\n        IF (.cycles % 64) < 12\n            lda #(.cycles / 64) - 1\n            sta WSYNC\n        ELSE\n            lda #(.cycles / 64)\n            sta WSYNC\n        ENDIF\n        sta TIM64T\n    ENDM\n\n; Wait for the RIOT timer and finish on a scanline boundary.\n    MAC TIMER_WAIT\n.waittimer\n        lda INTIM\n        bne .waittimer\n        sta WSYNC\n    ENDM\n"});
